minimum_matching <- function(costs) {
  a <- nrow(costs)
  b <- ncol(costs)
  if (a == 0L || b == 0L) return(matrix(integer(),0L,2L))
  flipped <- a > b
  matrix <- if (flipped) t(costs) else costs
  rows <- nrow(matrix)
  columns <- ncol(matrix)
  u <- numeric(rows+1L)
  v <- numeric(columns+1L)
  matched <- previous <- integer(columns+1L)
  for (row in seq_len(rows)) {
    matched[1L] <- row
    column <- 1L
    distances <- rep(Inf,columns+1L)
    used <- rep(FALSE,columns+1L)
    repeat {
      used[column] <- TRUE
      current_row <- matched[column]
      delta <- Inf
      following <- 0L
      for (candidate in seq.int(2L,columns+1L)) {
        if (used[candidate]) next
        reduced <- matrix[current_row,candidate-1L]-u[current_row+1L]-v[candidate]
        if (reduced < distances[candidate]) {
          distances[candidate] <- reduced
          previous[candidate] <- column
        }
        if (distances[candidate] < delta) {
          delta <- distances[candidate]
          following <- candidate
        }
      }
      for (candidate in seq_len(columns+1L)) {
        if (used[candidate]) {
          u[matched[candidate]+1L] <- u[matched[candidate]+1L]+delta
          v[candidate] <- v[candidate]-delta
        } else distances[candidate] <- distances[candidate]-delta
      }
      column <- following
      if (matched[column] == 0L) break
    }
    while (column != 1L) {
      following <- previous[column]
      matched[column] <- matched[following]
      column <- following
    }
  }
  columns_used <- which(matched[-1L] != 0L)
  pairs <- cbind(matched[columns_used+1L],columns_used)
  if (flipped) pairs <- pairs[,2:1,drop=FALSE]
  pairs[order(pairs[,1L],pairs[,2L]),,drop=FALSE]
}
optimal_assignment <- function(rows,columns,usable) {
  if (rows == 0L || columns == 0L || !any(is.finite(usable))) return(matrix(integer(),0L,2L))
  penalty <- (min(rows,columns)+1L)*(max(1,usable[is.finite(usable)])+1)
  costs <- usable
  costs[!is.finite(costs)] <- penalty
  pairs <- minimum_matching(costs)
  keep <- vapply(seq_len(nrow(pairs)),function(i) is.finite(usable[pairs[i,1L],pairs[i,2L]]),logical(1))
  pairs[keep,,drop=FALSE]
}

squared_distance <- function(a,b) {
  dx <- a[1L]-b[1L]
  dy <- a[2L]-b[2L]
  dx*dx+dy*dy
}
distance <- function(a,b) sqrt(squared_distance(a,b))
ospa <- function(first,second,cutoff) {
  if (!length(first) && !length(second)) return(0)
  if (!length(first) || !length(second)) return(cutoff)
  smaller <- if (length(first) <= length(second)) first else second
  larger <- if (length(first) <= length(second)) second else first
  costs <- matrix(0,length(smaller),length(larger))
  for (i in seq_along(smaller)) for (j in seq_along(larger)) {
    clipped <- min(cutoff,distance(smaller[[i]],larger[[j]]))
    costs[i,j] <- clipped*clipped
  }
  matches <- minimum_matching(costs)
  cost <- ordered_total(vapply(
      seq_len(nrow(matches)),
      function(i) costs[matches[i,1L],matches[i,2L]],
      numeric(1)
  ))
  sqrt((cost+cutoff*cutoff*(length(larger)-length(smaller)))/length(larger))
}
continuity <- function(labels) {
  covered <- groups <- swaps <- previous <- 0L
  previous_covered <- FALSE
  delay <- NULL
  for (index in seq_along(labels)) {
    label <- labels[index]
    if (label == 0L) {
      previous_covered <- FALSE
      next
    }
    covered <- covered+1L
    if (is.null(delay)) delay <- index-1L
    if (!previous_covered) groups <- groups+1L
    if (previous != 0L && label != previous) swaps <- swaps+1L
    previous <- label
    previous_covered <- TRUE
  }
  list(covered=covered,breaks=max(0L,groups-1L),swaps=swaps,delay=delay)
}
real_text <- function(value) {
  if (is.null(value)) return("-")
  text <- sprintf("%.4f",value)
  if (text == "-0.0000") "0.0000" else text
}

transition_matrix <- function(model,t) {
  f <- identity_matrix(if (model == "CV") 4L else 6L)
  f[1L,3L] <- f[2L,4L] <- t
  if (model == "CA") {
    f[1L,5L] <- f[2L,6L] <- t*t/2
    f[3L,5L] <- f[4L,6L] <- t
  }
  f
}
process_noise <- function(model,t,q) {
  if (model == "CV") {
    entries <- list(c(1,1,q*t*t*t/3),c(1,3,q*t*t/2),c(3,3,q*t))
    result <- matrix(0,4L,4L)
  } else {
    entries <- list(
        c(1,1,q*t*t*t*t*t/20),
        c(1,3,q*t*t*t*t/8),
        c(1,5,q*t*t*t/6),
        c(3,3,q*t*t*t/3),
        c(3,5,q*t*t/2),
        c(5,5,q*t)
    )
    result <- matrix(0,6L,6L)
  }
  for (axis in 0:1) for (entry in entries) {
    row <- as.integer(entry[1L])+axis
    column <- as.integer(entry[2L])+axis
    result[row,column] <- result[column,row] <- entry[3L]
  }
  result
}
new_kalman <- function(model,q,sigma,velocity_variance,acceleration_variance,measurement) {
  n <- if (model == "CV") 4L else 6L
  variances <- c(sigma*sigma,sigma*sigma,velocity_variance,velocity_variance)
  if (n == 6L) variances <- c(variances,acceleration_variance,acceleration_variance)
  h <- matrix(0,2L,n)
  h[1L,1L] <- h[2L,2L] <- 1
  list2env(
      list(
          model=model,
          q=q,
          x=c(measurement,rep(0,n-2L)),
          p=diagonal_matrix(variances),
          h=h,
          r=diagonal_matrix(c(sigma*sigma,sigma*sigma)),
          f=NULL,
          xp=NULL,
          pp=NULL
      ),
      parent=emptyenv()
  )
}
predict_filter <- function(filter,interval) {
  filter$f <- transition_matrix(filter$model,interval)
  filter$x <- matrix_vector(filter$f,filter$x)
  filter$p <- matrix_product(
      matrix_product(filter$f,filter$p),
      t(filter$f)
  )+process_noise(filter$model,interval,filter$q)
  filter$xp <- filter$x
  filter$pp <- filter$p
}
innovation <- function(filter,measurement) {
  residual <- measurement-matrix_vector(filter$h,filter$x)
  covariance <- matrix_product(matrix_product(filter$h,filter$p),t(filter$h))+filter$r
  precision <- matrix_inverse(covariance)
  list(residual=residual,covariance=covariance,precision=precision,distance2=quadratic2(residual,precision))
}
update_filter <- function(filter,measurement,info=innovation(filter,measurement)) {
  gain <- matrix_product(matrix_product(filter$p,t(filter$h)),info$precision)
  correction <- identity_matrix(length(filter$x))-matrix_product(gain,filter$h)
  filter$x <- filter$x+matrix_vector(gain,info$residual)
  filter$p <- matrix_product(
      matrix_product(correction,filter$p),
      t(correction)
  )+matrix_product(matrix_product(gain,filter$r),t(gain))
  likelihood <- -log(2*pi)-log(determinant2(info$covariance))/2-info$distance2/2
  list(distance2=info$distance2,likelihood=likelihood,covariance=info$covariance)
}
filter_snapshot <- function(filter) list(x=filter$x,p=filter$p,xp=filter$xp,pp=filter$pp,f=filter$f)
smooth <- function(history) {
  states <- vector("list",length(history))
  states[[length(states)]] <- history[[length(history)]]$x
  if (length(history) > 1L) for (index in seq.int(length(history)-1L,1L)) {
    current <- history[[index]]
    following <- history[[index+1L]]
    gain <- matrix_product(matrix_product(current$p,t(following$f)),matrix_inverse(following$pp))
    states[[index]] <- current$x+matrix_vector(gain,states[[index+1L]]-following$xp)
  }
  states
}

ordered_total <- function(values) {
  result <- 0
  for (value in values) result <- result+value
  result
}
diagonal_matrix <- function(values) diag(values,nrow=length(values),ncol=length(values))
identity_matrix <- function(n) diagonal_matrix(rep(1,n))
matrix_product <- function(a,b) {
  result <- matrix(0,nrow(a),ncol(b))
  for (i in seq_len(nrow(a))) for (j in seq_len(ncol(b))) result[i,j] <- ordered_total(a[i,]*b[,j])
  result
}
matrix_vector <- function(a,vector) vapply(
    seq_len(nrow(a)),
    function(i) ordered_total(a[i,]*vector),
    numeric(1)
)
matrix_inverse <- function(a) {
  n <- nrow(a)
  augmented <- cbind(a,identity_matrix(n))
  for (column in seq_len(n)) {
    pivot <- augmented[column,column]
    for (j in seq_len(2L*n)) augmented[column,j] <- augmented[column,j]/pivot
    for (row in seq_len(n)) {
      if (row == column) next
      factor <- augmented[row,column]
      for (j in seq_len(2L*n)) augmented[row,j] <- augmented[row,j]-factor*augmented[column,j]
    }
  }
  augmented[,seq.int(n+1L,2L*n),drop=FALSE]
}
determinant2 <- function(a) a[1L,1L]*a[2L,2L]-a[1L,2L]*a[2L,1L]
quadratic2 <- function(v,a) v[1L]*(a[1L,1L]*v[1L]+a[1L,2L]*v[2L])+v[2L]*(a[2L,1L]*v[1L]+a[2L,2L]*v[2L])
